function parseAddress(value) {
  const raw = String(value || "").trim();
  if (!raw) return { email: "", name: "" };

  if (typeof value === "object" && value !== null) {
    const email = String(value.address || value.email || "").trim();
    const name = String(value.name || value.text || "").trim();
    return { email, name };
  }

  const match = raw.match(/^(.*)<([^>]+)>$/);
  if (match) {
    return {
      name: String(match[1] || "").trim().replace(/^"|"$/g, ""),
      email: String(match[2] || "").trim()
    };
  }

  return { name: "", email: raw };
}

function splitAddresses(value) {
  if (Array.isArray(value)) {
    return value.map(v => parseAddress(v).email).filter(Boolean);
  }

  if (value && typeof value === "object") {
    if (Array.isArray(value.value)) return value.value.map(v => parseAddress(v).email).filter(Boolean);
    if (value.text) return splitAddresses(value.text);
  }

  const raw = String(value || "").trim();
  if (!raw) return [];
  return raw.split(",").map(v => parseAddress(v).email).filter(Boolean);
}

function getFirst(...values) {
  for (const value of values) {
    if (value !== undefined && value !== null && String(value).trim() !== "") return value;
  }
  return "";
}

function stripHtml(html) {
  return String(html || "").replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
}

function errorResult(code, message, source) {
  return [{
    json: {
      adapter_status: "error",
      component_id: "ADP-IMAP-INBOX",
      component_version: "v1",
